import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Identify potential drivers among clinical features
    clinical_features = [fid for fid, typ in zip(feats.ids, feats.types) if typ == 'clinical']

    # If we have clinical features, check if any drives the outcome strongly
    if clinical_features:
        # For each clinical feature, compute t-statistic against outcome
        best_clinical = None
        best_t = 0

        for fid in clinical_features:
            col_idx = feats.column(fid)
            feature_values = feats.x[:, col_idx]
            # Compute Welch's t-test between groups defined by outcome
            y0_vals = feature_values[feats.y == 0]
            y1_vals = feature_values[feats.y == 1]

            if len(y0_vals) > 0 and len(y1_vals) > 0:
                t_stat, _ = stats.ttest_ind(y0_vals, y1_vals, equal_var=False)
                if abs(t_stat) > abs(best_t):
                    best_t = t_stat
                    best_clinical = fid

        # If we found a strong clinical driver, use it
        if best_clinical and abs(best_t) > 2.0:
            return Design(
                drivers=(best_clinical,),
                columns=(best_clinical,),
                products=(),
                loadings={best_clinical: 1.0}
            )

    # No strong clinical driver found, proceed with other strategies

    # Build a list of all features with their effect sizes (t-statistics)
    effects = []
    for fid in feats.ids:
        col_idx = feats.column(fid)
        feature_values = feats.x[:, col_idx]
        y0_vals = feature_values[feats.y == 0]
        y1_vals = feature_values[feats.y == 1]

        if len(y0_vals) > 0 and len(y1_vals) > 0:
            t_stat, _ = stats.ttest_ind(y0_vals, y1_vals, equal_var=False)
            effects.append((abs(t_stat), fid))

    # Sort by effect size
    effects.sort(reverse=True)

    # Select top features
    top_features = [fid for _, fid in effects[:MAX_DRIVERS]]

    # Check for near-duplicates and remove them
    unique_features = set()
    filtered_features = []

    # Correlation-based deduplication
    correlations = {}
    for i, fid1 in enumerate(feats.ids):
        for j, fid2 in enumerate(feats.ids[i+1:], i+1):
            if abs(np.corrcoef(feats.x[:, feats.column(fid1)], feats.x[:, feats.column(fid2)])[0,1]) >= 0.6:
                correlations[fid1] = fid2
                break

    for fid in top_features:
        if not any(fid in pair for pair in correlations.items()):
            filtered_features.append(fid)

    # If no mechanism found, return empty design
    if not filtered_features:
        return Design(
            drivers=(),
            columns=(),
            products=(),
            loadings={}
        )

    # Simple weighted score using top features
    weights = {fid: 1.0 for fid in filtered_features}

    return Design(
        drivers=tuple(filtered_features[:MAX_DRIVERS]),
        columns=tuple(filtered_features),
        products=(),
        loadings=weights
    )

